BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0650000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 65, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "65", "printedPageNumber": 65, "pdfPageNumber": 448, "sequenceIndex": 55, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0650100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0650000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "band; and a person who hears the Azaan but does not go to the musjid for salaat with Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650200-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650300-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرج ابن مردويه عن كعب الحبر قال والذي أنزل التوراة على موسى والإنجيل على عيسى والزبور على داود والفرقان على محمد أنزلت هذه الآيات في الصلوات المكتوبات حيث ينادى بهن يوم يكشف عن ساق إلى قوله وهم سالمون، الصلوات الخمس إذا نودي بها وأخرج البيهقي في الشعب عن سعيد بن جبير قال الصلوات في الجماعات وأخرج البيهقي عن ابن عباس قال رجل يسمع الأذان فلا يجيب الصلاة كذا في الدر المنثور قلت وقام الآية يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650400-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Ka''b Ahbaar says, \"By Him who revealed the Torah to Moosa, the Injeel to Eesa, the Psalms to Dawood (Alayhimus salaam), and the Qur''an on Muhammad (Sallallaho alaihe wasallam), the following verses were revealed in respect of saying fardh salaat in those places (mosques) where the Azaan is said: \"On the day when the glory of Saaq is revealed and they are ordered to prostrate themselves, but are not able, with eyes downcast, abasement stupifying them. And they had been summoned to prostrate themselves when they were quite hale and healthy.\" (LXVIII: 42 and 43).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650500-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The glory of Saaq is a particular type of glory to be displayed on the Day of Judgement. All Muslims will fall prostrate on seeing this glory, but there will be some whose backs will turn stiff and they will be unable to prostrate themselves. As to who these unlucky persons would be, different interpretations have been given by different commentators. According to this hadith, which is also corroborated by another narrated by Hadhrat Ibn Abbas (Radhiyallaho anho), those shall be the persons who were called for salaat with jamaat, but did not go for it.\n\nA few other interpretations of the same are given below:—\n\n1. Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates on the authority of the Prophet (Sallallaho alaihe wasallam) that these shall be the persons who used to offer their salaat to be seen by other men.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0660000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 66, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "66", "printedPageNumber": 66, "pdfPageNumber": 449, "sequenceIndex": 56, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0660000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 66"}, {"id": "f0660100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "2. These shall be infidels who did not say salaat at all;\n\n3. These shall be the munaafiqeen. (Allah knows best and His knowledge is most perfect).\n\nWhat a terrible thing to be so abased and disgraced on the Day of Judgement that, while all Muslims shall fall prostrate at seeing Allah''s glory, those who neglected salaat with jamaat shall be singled out by their inability to do so.\n\nBesides these, many other warnings have been given against the neglect of jamaat. But as a matter of fact, none is necessary for a good Muslim to whom the word of Allah and His Apostle (Sallallaho alaihe wasallam) is all important. And for one who has no regard for their word, all such warnings are meaningless. But a time will come when every soul shall be called to account, and punished for its misdeeds, and then no amount of penitence shall be of any avail.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 66"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0670000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 67, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "67", "printedPageNumber": 67, "pdfPageNumber": 450, "sequenceIndex": 57, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0670100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0670200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER I", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0670300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "QUOTATIONS FROM THE QUR''AN", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0670400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—I", "sourceIdentifier": null, "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0670000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "PART III", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670100-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670200-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are many persons who offer their salaat and quite a lot of them are particular about jamaat as well, but they say it so imperfectly that, instead of earning blessings and reward for them, it is rejected forthwith. This, however, is not so bad as to discard salaat altogether, which as we have already learnt, is very serious. Although we are deprived of the rewards by saying a defective salaat, which is not accepted, yet we are saved from the insolence of neglecting and disobeying Allah''s commandments. However, when we spend our time, leave our work and undergo inconvenience, then why should we not see that we get the best return for our time and labour by saying our salaat as best as we can?\n\nThis third part is divided into three chapters. In the first chapter, a few quotations from the Holy Qur''an about the people who are condemned for their bad salaat and those who are praised for their good salaat, are given. In the second Chapter, stories about the salaat of a few lovers of Allah are collected. The third chapter consists of the sayings of the Prophet (Sallallaho alaihe wasallam) on this subject.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670300-0000-4000-8000-000000000001", "structuralNodeId": "b0670200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670400-0000-4000-8000-000000000001", "structuralNodeId": "b0670300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "QUOTATIONS FROM THE QUR''AN", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670500-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670600-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670700-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Their flesh and their blood reach not Allah, but devotion from you reacheth to Him.\" (XXII: 37)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670800-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Although this particular verse refers to the animal sacrifice, yet in principle it equally applies to all other rituals. It is sincerity and devotion in a service by which its acceptance would be judged by Allah. Hadhrat Mu''aaz (Radhiyallaho", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
